#!/usr/bin/env bash
# Generated by wikiloop build. Edit wikiloop.toml or guides/, not this file.
# Check prerequisites, then install the acme-wiki plugin for the selected agents.
# Missing tools and logins are reported with a hint; only the plugin is installed.
# Works both from a clone and when downloaded by bootstrap.sh.
set -uo pipefail

REPO="acme/ai-wiki"
MARKETPLACE="acme-wiki"
PLUGIN="acme-wiki@acme-wiki"
KNOWN="$HOME/.claude/plugins/known_marketplaces.json"

usage() {
  cat <<'HELP'
Usage: install.sh [--agents claude,codex|all] [--check | --update] [--project DIR]

Without --agents, ask which agents to use (Claude Code, Codex, or both).
  --agents LIST  Comma-separated agents; skips the prompt. "all" selects both.
  --check        Report prerequisites and installation status without installing.
                 Without a terminal, check the agents found on PATH.
  --update       Update the plugin for the selected agents.
  --project DIR  Also pin Claude Code in DIR/.claude/settings.json.
                 Implies --agents claude; cannot be combined with Codex.
  -h, --help     Show this help.

Noninteractive installation requires --agents. Start a new session afterwards.
HELP
}

die() { echo "$*" >&2; exit 1; }
usage_error() { echo "$*" >&2; usage >&2; exit 2; }

check_only=false
update_only=false
project=""
agents=""
while [ $# -gt 0 ]; do
  case "$1" in
    --check) check_only=true; shift ;;
    --agents|--project)
      [ $# -ge 2 ] && [ -n "$2" ] && [[ "$2" != --* ]] || usage_error "$1 needs a value"
      if [ "$1" = --agents ]; then agents="$2"; else project="$2"; fi
      shift 2 ;;
    --update) update_only=true; shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage_error "unknown option: $1" ;;
  esac
done

$check_only && $update_only && usage_error "--check and --update cannot be combined"
[ -n "$project" ] && $update_only && usage_error "--project and --update cannot be combined"

# Read from the controlling terminal: stdin may contain the downloaded script.
if [ -z "$agents" ]; then
  if [ -n "$project" ]; then
    agents=claude
  elif { exec 3<>/dev/tty; } 2>/dev/null; then
    printf 'Install for which agents? 1) Claude Code  2) Codex  3) Both\nChoose [1/2/3]: ' >&3
    IFS= read -r agents <&3 || die "No selection; pass --agents claude,codex"
    exec 3>&-
  elif $check_only; then
    command -v claude >/dev/null 2>&1 && agents=claude
    command -v codex >/dev/null 2>&1 && agents="${agents:+$agents,}codex"
    [ -n "$agents" ] || usage_error "No supported agent found; pass --agents claude or --agents codex"
  else
    usage_error "No terminal available; pass --agents claude,codex"
  fi
fi

use_claude=false
use_codex=false
case "$agents" in
  1) agents=claude ;;
  2) agents=codex ;;
  3|all) agents=claude,codex ;;
esac
case "$agents" in
  ,*|*,|*,,*) usage_error "Invalid agents: $agents" ;;
esac
IFS=',' read -r -a selected_agents <<<"$agents"
for agent in "${selected_agents[@]}"; do
  case "$agent" in
    claude) use_claude=true ;;
    codex) use_codex=true ;;
    *) usage_error "Unsupported agent: $agent (choose claude, codex, or all)" ;;
  esac
done
if [ -n "$project" ] && $use_codex; then
  usage_error "--project is only supported with --agents claude"
fi

# ---------------------------------------------------------------------------
# Reporting and helpers

required_failed=0

if [ -t 1 ]; then
  OK="$(printf '\033[32m ok \033[0m')"
  BAD="$(printf '\033[31mFAIL\033[0m')"
  MISS="$(printf '\033[33mmiss\033[0m')"
else
  OK=" ok "; BAD="FAIL"; MISS="miss"
fi

line() { printf '  %s  %-46s %s\n' "$1" "$2" "${3:-}"; }

have() { command -v "$1" >/dev/null 2>&1; }

# step <tier> <name> <hint> <check>
# check is a shell snippet. A failed required step is remembered and blocks the plugin install.
step() {
  local tier="$1" name="$2" hint="$3" check="$4"

  if eval "$check" >/dev/null 2>&1; then
    line "$OK" "$name"
    return 0
  fi

  if [ "$tier" = required ]; then
    required_failed=1
    line "$BAD" "$name" "-> $hint"
  else
    line "$MISS" "$name" "-> $hint"
  fi
  return 1
}

if [ "$(uname)" = Darwin ]; then
  hint_gh="brew install gh"
else
  hint_gh="https://github.com/cli/cli/blob/trunk/docs/install_linux.md"
fi

# Checks read the whole output first: with pipefail, `cmd | grep -q` fails whenever grep
# exits before cmd has finished writing.
has_kube_context() {
  grep -qx "$1" <<<"$(kubectl config get-contexts -o name 2>/dev/null)"
}

# has_mcp <name>: an MCP server whose name contains <name> is configured for Claude Code.
has_mcp() {
  python3 - "$1" <<'PY'
import json, os, sys
for path in (os.path.expanduser("~/.claude.json"), os.path.expanduser("~/.claude/settings.json")):
    try:
        servers = json.load(open(path)).get("mcpServers", {})
    except (OSError, ValueError):
        continue
    if any(sys.argv[1] in name.lower() for name in servers):
        sys.exit(0)
sys.exit(1)
PY
}

marketplace_configured() {
  grep -qE "(^|[[:space:]])$MARKETPLACE\$" <<<"$(claude plugin marketplace list 2>/dev/null)"
}

plugin_installed() {
  grep -q "$PLUGIN" <<<"$(claude plugin list 2>/dev/null)"
}

codex_marketplace_present() {
  python3 -c '
import json, sys
try:
    present = any(m["name"] == sys.argv[1] for m in json.load(sys.stdin)["marketplaces"])
except (ValueError, KeyError, TypeError):
    sys.exit(2)
sys.exit(0 if present else 1)
' "$MARKETPLACE"
}

codex_marketplace_configured() {
  codex plugin marketplace list --json | codex_marketplace_present
}

codex_plugin_ready() {
  codex plugin list --marketplace "$MARKETPLACE" --json | python3 -c '
import json, sys
sys.exit(0 if any(p.get("pluginId") == sys.argv[1] and p.get("installed") is True
                 and p.get("enabled") is True for p in json.load(sys.stdin)["installed"]) else 1)
' "$PLUGIN"
}

# ---------------------------------------------------------------------------
# Required: only the selected agents gate installation.

echo "required (selected agents: $agents)"

if $use_claude; then
  step required "Claude Code plugin CLI" \
    "install or update Claude Code" \
    'have claude && claude plugin --help'
fi
if $use_codex; then
  step required "Codex plugin CLI" \
    "install or update Codex to a version with codex plugin" \
    'have codex && codex plugin --help'
  if $update_only; then
    step required "Codex marketplace upgrade" \
      "update Codex to a version with codex plugin marketplace upgrade" \
      'have codex && codex plugin marketplace upgrade --help'
  fi
fi

step required "python3 (hooks and plugin status)" \
  "install python3 with your package manager" \
  'have python3'

if $update_only; then
  [ "$required_failed" -eq 0 ] || die "required checks failed; follow the FAIL hints and rerun"
  if $use_claude; then
    claude plugin marketplace update "$MARKETPLACE" || die "Claude Code update failed"
  fi
  if $use_codex; then
    codex plugin marketplace upgrade "$MARKETPLACE" || die "Codex marketplace update failed"
    codex plugin add "$PLUGIN" || die "Codex plugin update failed"
    codex_plugin_ready || die "Codex plugin is not installed and enabled"
  fi
  echo "updated; start a new session"
  exit 0
fi

step required "git" \
  "install git with your package manager" \
  'have git'

step required "gh CLI" \
  "$hint_gh" \
  'have gh'

step required "gh logged in" \
  "gh auth login" \
  'have gh && gh auth status'

step required "access to $REPO" \
  "ask in #platform for access to acme/ai-wiki" \
  "have gh && gh api repos/$REPO --silent"

# The agents clone the marketplace over https; a token in gh alone does not help git.
step required "git can clone $REPO over https" \
  "gh auth setup-git" \
  "have git && GIT_TERMINAL_PROMPT=0 git ls-remote -q https://github.com/$REPO.git HEAD"

echo
echo "recommended (what this wiki's skills use)"
step recommended kubectl 'brew install kubernetes-cli' 'have kubectl'
step recommended 'kube context acme-prod-eu' 'see skills/map-infra' 'has_kube_context acme-prod-eu'
step optional 'Grafana MCP server in Claude Code' 'claude mcp add grafana ...' 'has_mcp grafana'

# ---------------------------------------------------------------------------
# The plugin

echo
if [ $required_failed -ne 0 ]; then
  echo "required checks failed; follow the FAIL hints and rerun"
  exit 1
fi

echo "plugin"

if $check_only; then
  if $use_claude; then
    step optional "Claude marketplace $MARKETPLACE" "claude plugin marketplace add $REPO" 'marketplace_configured'
    step optional "Claude plugin $PLUGIN" "claude plugin install $PLUGIN --scope user" 'plugin_installed'
  fi
  if $use_codex; then
    step optional "Codex marketplace $MARKETPLACE" "codex plugin marketplace add $REPO --ref main" 'codex_marketplace_configured'
    step optional "Codex plugin installed and enabled" "codex plugin add $PLUGIN" 'codex_plugin_ready'
  fi
  echo
  echo "required checks pass; rerun without --check to install the selected plugins."
  exit 0
fi

if $use_claude; then
  if marketplace_configured; then
    line "$OK" "marketplace $MARKETPLACE"
  else
    claude plugin marketplace add "$REPO" >/dev/null || { line "$BAD" "marketplace $MARKETPLACE" "-> claude plugin marketplace add $REPO"; exit 1; }
    line "$OK" "marketplace $MARKETPLACE" "(added)"
  fi

  if plugin_installed; then
    line "$OK" "plugin $PLUGIN"
  else
    claude plugin install "$PLUGIN" --scope user >/dev/null || { line "$BAD" "plugin $PLUGIN" "-> claude plugin install $PLUGIN --scope user"; exit 1; }
    line "$OK" "plugin $PLUGIN" "(installed)"
  fi

  # Auto-update is off for third-party marketplaces; flip it on for this one.
  python3 - "$KNOWN" "$MARKETPLACE" <<'PY' || die "Could not enable Claude Code auto-update"
import json, sys
path, name = sys.argv[1], sys.argv[2]
data = json.load(open(path))
if name not in data:
    sys.exit(f"{name} missing from {path}; marketplace add failed?")
data[name]["autoUpdate"] = True
json.dump(data, open(path, "w"), indent=2)
PY
  line "$OK" "auto-update"

  if [ -n "$project" ]; then
    settings="$project/.claude/settings.json"
    mkdir -p "$(dirname "$settings")" || die "Could not create project settings directory"
    python3 - "$settings" "$REPO" "$MARKETPLACE" "$PLUGIN" <<'PY' || die "Could not write project settings"
import json, os, sys
path, repo, market, plugin = sys.argv[1:]
data = json.load(open(path)) if os.path.exists(path) else {}
data.setdefault("extraKnownMarketplaces", {})[market] = {
    "source": {"source": "github", "repo": repo, "ref": "main"},
    "autoUpdate": True,
}
# Claude Code reads enabledPlugins as {"name@marketplace": true|false}, not as a list.
enabled = data.setdefault("enabledPlugins", {})
if isinstance(enabled, list):  # written by an earlier version of this script
    enabled = data["enabledPlugins"] = {p: True for p in enabled}
enabled[plugin] = True
json.dump(data, open(path, "w"), indent=2)
open(path, "a").write("\n")
PY
    line "$OK" "pinned in $settings" "commit it so the whole team gets the wiki"
  fi
fi

if $use_codex; then
  # A failed list is an error, not evidence that the marketplace is absent.
  codex_markets="$(codex plugin marketplace list --json)" || die "Could not list Codex marketplaces"
  if codex_marketplace_present <<<"$codex_markets"; then
    line "$OK" "Codex marketplace $MARKETPLACE"
  else
    [ "$?" -eq 1 ] || die "Could not parse Codex marketplaces"
    codex plugin marketplace add "$REPO" --ref main || die "Could not add Codex marketplace"
  fi
  if ! codex_plugin_ready; then
    codex plugin add "$PLUGIN" || die "Could not install Codex plugin"
  fi
  codex_plugin_ready || die "Codex plugin is not installed and enabled"
  line "$OK" "Codex plugin installed and enabled"
fi

echo
echo "done. Start a new session to load the selected plugins."
if $use_codex; then
  echo "Codex runs plugin hooks only once trusted: open /hooks in a Codex session and trust the"
  echo "$MARKETPLACE hooks. Until then the skills work and the wiki loop does not."
fi
